//! Arabic contextual shaping, generated from the Unicode Character Database.
//!
//! Do not edit. See `tools/unicode-codegen/arabic_shaping.py`.
//!
//! Each row is a letter, its joining type, and its four presentation forms in the
//! order isolated, final, initial, medial. A letter with no initial or medial form —
//! every right-joining one — repeats its isolated and final, which is what keeps the
//! lookup a plain index rather than a branch.

/// How a character joins to its neighbours.
///
/// Unicode's joining types. `Transparent` is the one that carries the algorithm: a
/// diacritic sits *between* two letters without breaking their join, so the context a
/// letter sees has to look past any number of them.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Joining {
    /// Joins on both sides.
    Dual,
    /// Joins only to the letter before it.
    Right,
    /// Joins only to the letter after it.
    Left,
    /// Joins nothing itself but lets its neighbours join through it.
    Causing,
    /// Invisible to joining: a diacritic.
    Transparent,
    /// Joins nothing.
    None,
}

/// One letter's joining type and its four forms.
#[derive(Debug, Clone, Copy)]
pub struct Letter {
    /// The base code point, as text stores it.
    pub base: u32,
    /// How it joins.
    pub joining: Joining,
    /// Isolated, final, initial, medial.
    pub forms: [u32; 4],
}

